public OCFile getFileByPath(String path){
  Cursor c=getFileCursorForValue(ProviderTableMeta.FILE_PATH, path);
  OCFile file = null;
  try {
    if (c.moveToFirst()) {
      file = createFileInstance(c);
    }
    c.close();
    if (file == null && OCFile.ROOT_PATH.equals(path)) {
      try {
        return createRootDir();
      } catch (NumberFormatException e) {
        // Handle the NumberFormatException, e.g., log or rethrow
      }
    }
  } catch (SecurityException e) {
    // Handle the SecurityException, e.g., log or rethrow
  }
  return file;
}
